
import base64,gzip,os
F={
 'qaforge/runner.py':'',
 'qaforge/healer.py':'',
 'qaforge/initializer.py':'',
 'qaforge/cli.py':'',
 'qaforge/llm.py':'',
 'skills/heal-test/SKILL.md':'',
 '.github/workflows/test.yml':'',
 'GETTING-STARTED.md':'',
 'CHANGELOG.md':'',
 'LICENSE':'',
 'README.md':'',
}

for p,d in F.items():
    dr=os.path.dirname(p)
    if dr: os.makedirs(dr,exist_ok=True)
    open(p,"wb").write(gzip.decompress(base64.b64decode(d)))
    print("wrote",p)
print("Done -",len(F),"files written")